referenceSolutions.javascript:
export function solve(values) {
  const out = [];
  const walk = (x) => {
    if (!x) return;
    if (Array.isArray(x)) {
      for (const y of x) walk(y);
    } else if (typeof x === "object") {
      for (const k of Object.keys(x)) if (x[k]) out.push(k);
    } else if (typeof x === "string" || typeof x === "number") out.push(String(x));
  };
  walk(values);
  return out.join(" ");
}

referenceSolutions.typescript:
export function solve(values: any[]): any {
  const out: string[] = [];
  const walk = (x: any): void => {
    if (!x) return;
    if (Array.isArray(x)) {
      for (const y of x) walk(y);
    } else if (typeof x === "object") {
      for (const k of Object.keys(x)) if (x[k]) out.push(k);
    } else if (typeof x === "string" || typeof x === "number") out.push(String(x));
  };
  walk(values);
  return out.join(" ");
}
